-- Owner-approved Stage 1B matrix: S06 unmasked PII positive cases run at AAL2.
BEGIN;CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;SELECT extensions.plan(16);
SET LOCAL ROLE authenticated;SELECT lab_test.claim('11111111-1111-4111-8111-111111111111','authenticated');SELECT set_config('request.jwt.claims',jsonb_build_object('sub','11111111-1111-4111-8111-111111111111'::uuid,'role','authenticated','aal','aal2')::text,true);CREATE TEMP TABLE z(id text,ok boolean)ON COMMIT DROP;GRANT INSERT,SELECT ON z TO authenticated,anon;
INSERT INTO z VALUES('S01-owner',(SELECT count(*)=2 FROM public.student_duplicate_warning_view)),('S02-owner',(SELECT count(*)>0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional KL One','other','KL-IDENTITY-1111','+60121110001','kl@example.invalid',DATE'2000-01-01'))),('S04-owner',lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)),('S05-owner',lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)),('S06-owner',(SELECT count(*)=1 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'))),('S07-owner',lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')),('S08-owner-cross-entity',NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa5','x')$q$)),('S09-owner',lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')),('S10-owner',NOT lab_test.probe($q$DELETE FROM public.programmes WHERE id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$q$)),('S11-owner',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S12-owner',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S13-owner',NOT lab_test.probe($q$DELETE FROM public.student_import_batches WHERE id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$)),('S14-owner',NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')),('S16-owner',NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students'));RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('22222222-2222-4222-8222-222222222222','authenticated');SELECT set_config('request.jwt.claims',jsonb_build_object('sub','22222222-2222-4222-8222-222222222222'::uuid,'role','authenticated','aal','aal2')::text,true);INSERT INTO z VALUES('S01-kl',(SELECT count(*)=1 AND bool_and(possible_duplicate_student_number LIKE'LAB-KL-%')FROM public.student_duplicate_warning_view)),('S02-kl',(SELECT count(*)>0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional KL One','other','KL-IDENTITY-1111','+60121110001','kl@example.invalid',DATE'2000-01-01'))),('S03-kl',(SELECT count(*)=0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional PG One','other','PG-IDENTITY-2222','+60122220002','pg@example.invalid',DATE'2001-02-02'))),('S04-kl',lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)),('S05-kl',NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)),('S06-kl',(SELECT count(*)=1 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'))AND(SELECT count(*)=0 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3'))),('S07-kl',lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')),('S08-kl',NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','x')$q$)),('S09-kl',lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')),('S10-kl',NOT lab_test.probe($q$DELETE FROM public.programme_intakes WHERE id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1'$q$)),('S11-kl',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S12-kl',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S13-kl',NOT lab_test.probe($q$DELETE FROM public.student_legacy_records WHERE id='99999999-9999-4999-8999-999999999999'$q$)),('S14-kl',NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')AND lab_test.probe($q$SELECT public.generate_enrolment_number((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'cccccccc-cccc-4ccc-8ccc-ccccccccccc1')$q$)),('S16-kl',NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students'));RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('33333333-3333-4333-8333-333333333333','authenticated');SELECT set_config('request.jwt.claims',jsonb_build_object('sub','33333333-3333-4333-8333-333333333333'::uuid,'role','authenticated','aal','aal2')::text,true);INSERT INTO z VALUES('S01-pg',(SELECT count(*)=1 AND bool_and(possible_duplicate_student_number LIKE'LAB-PG-%')FROM public.student_duplicate_warning_view)),('S02-pg',(SELECT count(*)>0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional PG One','other','PG-IDENTITY-2222','+60122220002','pg@example.invalid',DATE'2001-02-02'))),('S03-pg',(SELECT count(*)=0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional KL One','other','KL-IDENTITY-1111','+60121110001','kl@example.invalid',DATE'2000-01-01'))),('S04-pg',lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)),('S05-pg',NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)),('S06-pg',(SELECT count(*)=1 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3'))),('S07-pg',lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4')),('S08-pg',NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','x')$q$)),('S09-pg',lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3')),('S10-pg',NOT lab_test.probe($q$DELETE FROM public.enrolments WHERE id='dddddddd-dddd-4ddd-8ddd-dddddddddddd'$q$)),('S11-pg',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S12-pg',lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))),('S13-pg',NOT lab_test.probe($q$DELETE FROM public.student_import_batches WHERE id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$)),('S14-pg',NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')AND lab_test.probe($q$SELECT public.generate_enrolment_number((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'cccccccc-cccc-4ccc-8ccc-ccccccccccc2')$q$)),('S16-pg',NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students'));RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('44444444-4444-4444-8444-444444444444','authenticated');INSERT INTO z SELECT'S'||lpad(n::text,2,'0')||'-deny',CASE n WHEN 1 THEN(SELECT count(*)=0 FROM public.student_duplicate_warning_view)WHEN 2 THEN(SELECT count(*)=0 FROM public.find_student_duplicate_warnings(NULL,(SELECT id FROM public.entities WHERE short_code='IETA'),'x','other','x',NULL,NULL,NULL))WHEN 3 THEN true WHEN 4 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)WHEN 5 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)WHEN 6 THEN(SELECT count(*)=0 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'))WHEN 7 THEN NOT lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')WHEN 8 THEN NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','x')$q$)WHEN 9 THEN NOT lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')WHEN 10 THEN NOT lab_test.probe($q$DELETE FROM public.programmes WHERE id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$q$)WHEN 11 THEN NOT lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))WHEN 12 THEN NOT lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))WHEN 13 THEN NOT lab_test.probe($q$DELETE FROM public.student_import_batches WHERE id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$)WHEN 14 THEN NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')WHEN 15 THEN true WHEN 16 THEN NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students')END FROM generate_series(1,16)n;RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('55555555-5555-4555-8555-555555555555','authenticated');INSERT INTO z SELECT'S'||lpad(n::text,2,'0')||'-inactive',CASE n WHEN 1 THEN(SELECT count(*)=0 FROM public.student_duplicate_warning_view)WHEN 2 THEN(SELECT count(*)=0 FROM public.find_student_duplicate_warnings(NULL,(SELECT id FROM public.entities WHERE short_code='IETA'),'x','other','x',NULL,NULL,NULL))WHEN 3 THEN true WHEN 4 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)WHEN 5 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)WHEN 6 THEN(SELECT count(*)=0 FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'))WHEN 7 THEN NOT lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')WHEN 8 THEN NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','x')$q$)WHEN 9 THEN NOT lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')WHEN 10 THEN NOT lab_test.probe($q$DELETE FROM public.programmes WHERE id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$q$)WHEN 11 THEN NOT lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))WHEN 12 THEN NOT lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')))WHEN 13 THEN NOT lab_test.probe($q$DELETE FROM public.student_import_batches WHERE id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$)WHEN 14 THEN NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')WHEN 15 THEN true WHEN 16 THEN NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students')END FROM generate_series(1,16)n;RESET ROLE;
SET LOCAL ROLE anon;SELECT lab_test.claim(NULL,'anon');INSERT INTO z SELECT'S'||lpad(n::text,2,'0')||'-anon',CASE n WHEN 1 THEN NOT lab_test.probe('SELECT*FROM public.student_duplicate_warning_view')WHEN 2 THEN NOT lab_test.probe($q$SELECT*FROM public.find_student_duplicate_warnings(NULL,(SELECT id FROM public.entities WHERE short_code='IETA'),'x','other','x',NULL,NULL,NULL)$q$)WHEN 3 THEN true WHEN 4 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='IETA'))$q$)WHEN 5 THEN NOT lab_test.probe($q$SELECT public.generate_student_number((SELECT id FROM public.entities WHERE short_code='PLC'))$q$)WHEN 6 THEN NOT lab_test.probe($q$SELECT*FROM public.get_student_sensitive_identity('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$q$)WHEN 7 THEN NOT lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')WHEN 8 THEN NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','x')$q$)WHEN 9 THEN NOT lab_test.academic(lab_test.entity_id('IETA'),lab_test.branch_id('KL'),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')WHEN 10 THEN NOT lab_test.probe($q$DELETE FROM public.programmes WHERE id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$q$)WHEN 11 THEN NOT lab_test.import_flow(lab_test.entity_id('IETA'),lab_test.branch_id('KL'))WHEN 12 THEN NOT lab_test.import_flow(lab_test.entity_id('IETA'),lab_test.branch_id('KL'))WHEN 13 THEN NOT lab_test.probe($q$DELETE FROM public.student_import_batches WHERE id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$)WHEN 14 THEN NOT lab_test.probe('SELECT*FROM app_private.student_enrolment_number_sequences')WHEN 15 THEN true WHEN 16 THEN NOT lab_test.probe('SELECT identity_number_fingerprint,email_normalised,phone_normalised FROM public.students')END FROM generate_series(1,16)n;RESET ROLE;
INSERT INTO z VALUES('S15-grants',NOT EXISTS(SELECT 1 FROM information_schema.role_table_grants WHERE grantee IN('authenticated','anon')AND table_schema='public'AND table_name IN('programmes','programme_intakes','enrolments','student_import_batches','student_import_rows','student_legacy_records')AND privilege_type IN('TRUNCATE','TRIGGER','REFERENCES')));
SELECT extensions.ok(bool_and(ok),'[S01] complete owner/KL/PG/unauthorised/inactive/anonymous view matrix')FROM z WHERE id LIKE'S01-%';SELECT extensions.ok(bool_and(ok),'[S02] complete duplicate RPC matrix')FROM z WHERE id LIKE'S02-%';SELECT extensions.ok(bool_and(ok),'[S03] other-branch duplicate isolation matrix')FROM z WHERE id LIKE'S03-%';SELECT extensions.ok(bool_and(ok),'[S04] accessible student-number matrix')FROM z WHERE id LIKE'S04-%';SELECT extensions.ok(bool_and(ok),'[S05] inaccessible-entity student-number matrix')FROM z WHERE id LIKE'S05-%';SELECT extensions.ok(bool_and(ok),'[S06] sensitive identity permission/scope matrix')FROM z WHERE id LIKE'S06-%';SELECT extensions.ok(bool_and(ok),'[S07] same-branch merge matrix')FROM z WHERE id LIKE'S07-%';SELECT extensions.ok(bool_and(ok),'[S08] cross-branch/entity merge matrix')FROM z WHERE id LIKE'S08-%';SELECT extensions.ok(bool_and(ok),'[S09] programme/intake/enrolment write matrix')FROM z WHERE id LIKE'S09-%';SELECT extensions.ok(bool_and(ok),'[S10] hard-delete denial matrix')FROM z WHERE id LIKE'S10-%';SELECT extensions.ok(bool_and(ok),'[S11] import create/update matrix')FROM z WHERE id LIKE'S11-%';SELECT extensions.ok(bool_and(ok),'[S12] preview replacement and revert matrix')FROM z WHERE id LIKE'S12-%';SELECT extensions.ok(bool_and(ok),'[S13] direct batch/legacy deletion matrix')FROM z WHERE id LIKE'S13-%';SELECT extensions.ok(bool_and(ok),'[S14] private counter and enrolment RPC matrix')FROM z WHERE id LIKE'S14-%';SELECT extensions.ok(bool_and(ok),'[S15] dangerous privileges absent')FROM z WHERE id LIKE'S15-%';SELECT extensions.ok(bool_and(ok),'[S16] direct protected-column access denied')FROM z WHERE id LIKE'S16-%';SELECT*FROM extensions.finish();ROLLBACK;